import commentClassification from './comment-classification.mjs';
import referenceIntegrity from './reference-integrity.mjs';
import markdownLinkLabels from './markdown-link-labels.mjs';
import taskLifecycle from './task-lifecycle.mjs';
import warningSuppression from './warning-suppression.mjs';
import filePlacement from './file-placement.mjs';
import squashMergeHistory from './squash-merge-history.mjs';
import claudeMdLength from './claude-md-length.mjs';
import generatedMergeDriver from './generated-merge-driver.mjs';
import sharedConstants from './shared-constants.mjs';
import catalogCompleteness from './catalog-completeness.mjs';
import claudiniteIsolation from './claudinite-isolation.mjs';
import schedulerWorkflowShape from './scheduler-workflow-shape.mjs';
import taskDeclarationShape from './task-declaration-shape.mjs';
import taskDeclarationMatchesFolder from './task-declaration-matches-folder.mjs';
import taskPhaseDiscipline from './task-phase-discipline.mjs';
import conformanceWorkflow from './conformance-workflow.mjs';
import rulesLineLength from './rules-line-length.mjs';
import rulesIndexCurrent from './rules-index-current.mjs';

// The baseline pack: working discipline, the task lifecycle, and the core
// checks. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly update
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
export default {
  id: 'basics',
  // 2 — the mechanism rename (migrations/2026-08-13-mechanism-versioned). The FIRST
  // bump this pack has taken, and the invariant it establishes: a record's declared
  // `version` must be ≤ this number, and this number must MOVE for that record to
  // reach a member already at the previous one. `migrationApplies` is `want > have`
  // against the stamped version, and what gets stamped is this manifest's number — so
  // a record declaring a version above it would re-apply every cycle, forever,
  // draining never.
  version: 2,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; GitHub Actions workflow or platform behaviour — github-actions; git procedure — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // The consumer-isolation wall rides the barriers mechanism: basics requires
  // the barriers pack and CONTRIBUTES the fixed barrier as manifest data
  // (claudinite-isolation.mjs — pure data, no cross-pack import;
  // pack-independence). git-github carries the git/GitHub side of the task
  // lifecycle (#385). Universal because basics is declared everywhere; the
  // requires closure materializes both declarations alongside it.
  requires: ['barriers', 'git-github'],
  contributes: { barriers: [claudiniteIsolation] },
  // Rules that audit the repo as it stands, whatever this session did.
  worldRules: [
    markdownLinkLabels,
    rulesLineLength,
    warningSuppression,
    filePlacement,
    claudeMdLength,
    generatedMergeDriver,
    sharedConstants,
    catalogCompleteness,
    // The per-project scheduling conformance guards (scheduled-tasks.md):
    // scheduling is baseline Claudinite discipline — the scheduler workflow and
    // the task-declaration contract are guarded wherever basics is declared
    // (everywhere). All three are relevance-first: inert until the repo carries
    // the workflow / a tasks/<name>/task.mjs of its own.
    schedulerWorkflowShape,
    taskDeclarationShape,
    taskDeclarationMatchesFolder,
    // The precondition-is-the-only-gate discipline (owner, 2026-08-06): an
    // advisory hunt for tasks that "escape" — skip their work in the prework or
    // agentic phase after the precondition already said run.
    taskPhaseDiscipline,
    // And the CI half of the same discipline: a member whose world sweep cannot
    // run on a pull request has no gate, and its maintenance PR never lands.
    conformanceWorkflow,
    // The one channel a pack's rules reach a session on since #807. A repo whose
    // index is missing, stale or unimported runs with NO pack rules and cannot
    // tell — so the repo goes red, which is the only signal there is.
    rulesIndexCurrent,
  ],
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation.
  workRules: [
    commentClassification,
    referenceIntegrity,
    taskLifecycle,
    squashMergeHistory,
  ],
  // The baseline skills — general engineering practice every project's work
  // can call for, whatever its technology — bundled under skills/ in this pack's
  // own tree and mounted wherever basics is declared (which --init seeds
  // everywhere). When one stops being a baseline activity, move its directory to
  // the pack whose projects need it and move this line with it (#385 moved the
  // git/GitHub and Claudinite-lifecycle skills out).
  //
  // The baseline scheduled task every repo runs — `update`, the per-repo
  // self-refresh — lives in this pack's `tasks/update/`, discovered by the
  // scheduler's filesystem scan (engine/scheduler/discover.mjs), not declared
  // here. Being in basics — declared everywhere — makes it universal.
  skills: [
    'authoring-agent-docs',
    'bug-investigation',
    'bump-version',
    'file-placement',
    'repo-text-sweeps',
    'writing-tests',
  ],
};
===========
import growthConfig from './config-check.mjs';
import dedupIntegrity from './dedup-integrity.mjs';
import growthWriteScope from './growth-write-scope.mjs';

// Opt into the growth lifecycle: a repo declaring grow_with_claudinite contributes its
// hard-won lessons up to the Claudinite canon and prunes them back out once the canon
// owns them. This pack carries the REPO-side stages — extract, dedup, the weekly local
// pack discovery, and the weekly prose-to-checks sweep — as scheduled tasks under this pack's
// own `tasks/`, discovered by the scheduler's filesystem scan
// (engine/scheduler/discover.mjs), so none of them is declared here. The central
// promote stage — lifting portable lessons up into the shared canon — is a home-only
// duty that runs canon-side, outside this pack; its precondition targets exactly the
// members that declare THIS pack, minus any member whose entry sets config.promote:
// false (the promotion opt-out; extraction and dedup stay local either way).
//
// EXTRACTION IS ONE TASK OVER TWO SOURCES. growth-extract (tasks/growth-extract/)
// runs the extract-from-activity skill over the window's commits/PRs/issues and the
// extract-from-conversations skill over the captured logs, then the prose-to-checks
// skill over the prose it just wrote, and lands all of it in one PR delivered
// per the repo's delivery settings.
// The halves were two tasks firing in the same nightly slot against the same local
// packs; they shared the bar, the ladder and the dedup surface, so the split bought
// nothing and cost a second opus dispatch, a second PR, and two runs deduping
// against a corpus the other was concurrently writing.
//
// The pack also owns the CONVERSATION lifecycle: capture-log.mjs pushes a session's
// conversation onto the orphan conversation-logs branch (in-session — it needs the
// live transcript), driven by TWO events: merge-to-main's capture step, with the
// issue the merge closed, and session-end.mjs, with --issue 0, invoked by the
// engine's SessionEnd hook runner. The second is best-effort and captures what the
// first structurally cannot — sessions that never merge, and the post-merge tail of
// the ones that do; it is safe to double-write because capture deltas on the session
// id. growth-extract's conversation half then mines those pushed logs on its own
// access model — the logs branch is in the repo, so reading it, committing lessons to
// local packs, and pruning aged logs are plain local git; only posting the short
// summary behind each extracted rule on its issue uses the GitHub MCP tools —
// pruning logs past config.retention_days.
//
// And it owns the SKILL-USAGE metric the promotion ladder's skill-vs-prose call was
// missing: usage-fold (tasks/usage-fold/) counts skill loads and their activity
// denominators out of those same captured logs into a small tracked aggregate.
// Fleet-wide aggregation is NOT here — the canon knows mechanisms, never repos; that
// is the sheepdog pack's job, in the fleet-enforcer repo.
//
// growth-discover-packs is the weekly LOCAL pack-discovery reflection: the repo
// manifests its own stack, notices project-specific knowledge no canon pack homes,
// and authors a local pack for it under its own `.claudinite/local/packs/`.
//
// A declared pack (no fingerprint), seeded like tidy-repo: --init seeds it into every
// new repo, the one-time grow-with-claudinite-seed migration seeds the existing fleet,
// and baselining never re-adds it — so removing it is a durable opt-out.
//
// No adoption question over config.retention_days — the value stays unset (hidden)
// by default, which is fail-safe (capture-only, the prune deletes nothing) rather
// than something every adopter must weigh in on. A project that wants the prune
// active sets retention_days itself.
export default {
  id: 'grow_with_claudinite',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'rules and tasks for capturing lessons into local packs — extraction, dedup, conversation logs, skill-usage folding',
    excludes: 'repo housekeeping of issues, PRs and branches — that is tidy-repo; cross-repo fleet sweeps are sheepdog',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: null,
  worldRules: [growthConfig],
  workRules: [dedupIntegrity, growthWriteScope],
  skills: [
    'adopt-claudinite',
    'adopt-pack',
    'extract-from-activity',
    'extract-from-conversations',
    'generate-project-instructions',
    'growth-dedup',
    'prose-to-checks',
    'unattended-agents',
  ],
};

