import { finding } from '../../engine/checks/helpers/findings.mjs';
import { packEntryId } from '../../engine/pack_loader/pack-registry.mjs';

// The `core` pack is mandatory in every member: it carries Claudinite's own
// surface — the mount, the declaration, adoption, the update, the scheduled-task
// contract — and a repo running Claudinite without it is running the machinery
// with none of the machinery's rules.
//
// WHY THIS RULE IS IN `basics` AND NOT IN `core`. `run-active-pack-rules` filters
// on `isActive`, which reads the LITERAL `packs` list in .claudinite-checks.json —
// not the `requires` closure. So a rule inside `core` asserting that `core` is
// declared is inert in exactly the case it exists for: the pack whose absence it
// reports is the pack that would have to be present for it to run. It has to be
// hosted by a pack that is active independently, and `basics` is the one — seeded
// everywhere, required by nothing, and the pack that `requires` core.
//
// The id is a literal here rather than a walk of every active pack's `requires`,
// because a rule's `run` is synchronous and loading manifests is a dynamic import.
// The canon's own packs-tests/core/mandatory.test.mjs asserts the other half —
// that `basics.requires` really does name `core` — so the two cannot drift.
//
// ADVISORY UNTIL THE FLEET CARRIES IT (the `conformance-workflow` precedent, and
// the #555 failure both are drawn from): shipping this blocking would turn every
// member red on its very next update, before the record that declares `core` has
// reached it. It becomes blocking once the fleet is through — a one-line change.
const CORE = 'core';
const DECLARATION = '.claudinite-checks.json';

const rule = {
  id: 'core-declared',
  severity: 'advisory',
  description: `${DECLARATION} must declare the "${CORE}" pack — it is mandatory in every Claudinite member`,
  doc: 'packs/core/README.md',
  why: 'core carries Claudinite\'s own rules — the mount, the declaration, adoption, the update and the task contract — and a member that does not declare it runs the machinery with none of them',

  run(ctx) {
    // Relevance first: no declaration at all means this is not a member, and the
    // world runner already reports a malformed one as the settings error it is.
    if (!ctx.files.includes(DECLARATION)) return [];
    const declared = Array.isArray(ctx.config?.packs) ? ctx.config.packs : [];
    if (declared.some((entry) => packEntryId(entry) === CORE)) return [];
    return [finding(rule, {
      file: DECLARATION,
      what: `does not declare the mandatory "${CORE}" pack`,
      fix: `add "${CORE}" to "packs" — it is basics' own dependency, so the requires closure writes it back the next time the declaration is written`,
    })];
  },
};

export default rule;

