import claudiniteIsolation from './claudinite-isolation.mjs';
import rulesIndexCurrent from './rules-index-current.mjs';
import catalogCompleteness from './catalog-completeness.mjs';
import conformanceWorkflow from './conformance-workflow.mjs';
import schedulerWorkflowShape from './scheduler-workflow-shape.mjs';
import taskDeclarationShape from './task-declaration-shape.mjs';
import taskDeclarationMatchesFolder from './task-declaration-matches-folder.mjs';
import taskPhaseDiscipline from './task-phase-discipline.mjs';

// Claudinite's own surface in a repo that runs it: the vendored mount, the
// declaration that activates a pack, adopting Claudinite and adopting a pack,
// the self-refresh that keeps the mount current, and the contract every
// scheduled task is written to. Every rule here judges CLAUDINITE machinery —
// nothing about the project's own code, its technology or its process.
//
// WHY IT IS ITS OWN PACK. These rules and skills were scattered across the two
// packs that happened to be seeded everywhere — `basics` (working discipline)
// and `grow_with_claudinite` (lesson capture) — and neither pack's
// `ruleRoutingGuidance` claims this territory. So a session extracting a lesson
// about the mount, an adoption or an update had nowhere correct to route it,
// and read the two hosts' guidance as an honest "no pack owns this".
//
// MANDATORY, and enforced from OUTSIDE. `basics` requires this pack, so the
// `requires` closure materializes the declaration wherever a declaration is
// written and vendors this pack's content wherever `basics` is declared. The
// check that a member actually carries the declaration lives in `basics`
// (core-declared.mjs) rather than here, for the reason that check's own header
// gives: a rule inside this pack does not run in the one case it exists for.
export default {
  id: 'core',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'using Claudinite itself — the vendored mount, the pack declaration, bootstrapping a repo, adopting packs, the self-refresh update, and the scheduled-task contract',
    excludes: 'general working discipline and the issue-branch-PR lifecycle — basics; capturing lessons into packs — grow_with_claudinite; git and GitHub procedure — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // The consumer-isolation wall rides the barriers mechanism: this pack
  // CONTRIBUTES the fixed barrier as manifest data (claudinite-isolation.mjs —
  // pure data, no cross-pack import; pack-independence).
  requires: ['barriers'],
  contributes: { barriers: [claudiniteIsolation] },
  worldRules: [
    // The mount's two load-bearing surfaces: the index that carries pack prose
    // into a session, and the catalog that says which packs exist to adopt.
    rulesIndexCurrent,
    catalogCompleteness,
    // The member's plumbing — the CI gate its maintenance PR merges through, and
    // the scheduler workflow that fires its tasks. Both relevance-first: inert
    // until the repo carries the artifact.
    conformanceWorkflow,
    schedulerWorkflowShape,
    // The scheduled-task contract (scheduled-tasks.md), likewise inert until the
    // repo carries a tasks/<name>/task.mjs of its own.
    taskDeclarationShape,
    taskDeclarationMatchesFolder,
    taskPhaseDiscipline,
  ],
  workRules: [],
  // Bootstrapping a repo, and adding a pack to one already bootstrapped. Both
  // were bundled in grow_with_claudinite, whose subject is lesson capture.
  skills: [
    'adopt-claudinite',
    'adopt-pack',
  ],
  // The scheduled task that acts on a repo's pack-adoption requests lives in this
  // pack's `tasks/`, discovered by the scheduler's filesystem scan
  // (engine/scheduler/discover.mjs), not declared here.
};

